namespace UniversityCourseCatalog.Models;

public class Department
{
    public string Id { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public string Id { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public string DepartmentId { get; set; } = string.Empty;
    public string DepartmentName { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    [StringLength(100)]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Za-z0-9\-]+$", ErrorMessage = "Student ID must contain only letters, numbers, and hyphens.")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    public string CourseId { get; set; } = string.Empty;
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = "cs", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = "math", Name = "Mathematics", Description = "Pure and applied mathematics including statistics and analysis." },
            new() { Id = "eng", Name = "English", Description = "Literature, writing, and language studies." },
            new() { Id = "phys", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = "hist", Name = "History", Description = "Examination of past events, civilizations, and cultures." },
        };

        _courses = new List<Course>
        {
            new()
            {
                Id = "cs101", Code = "CS 101", Title = "Introduction to Programming",
                Description = "Fundamentals of programming using Python. Covers variables, control flow, functions, and basic data structures.",
                DepartmentId = "cs", DepartmentName = "Computer Science", Credits = 3,
                Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen",
                InstructorBio = "Dr. Chen specializes in programming pedagogy and has taught introductory courses for over 15 years.",
                IsFeatured = true
            },
            new()
            {
                Id = "cs201", Code = "CS 201", Title = "Data Structures & Algorithms",
                Description = "Study of fundamental data structures (trees, graphs, hash tables) and algorithm design techniques.",
                DepartmentId = "cs", DepartmentName = "Computer Science", Credits = 4,
                Schedule = "Tue/Thu 10:30–11:45 AM", InstructorName = "Dr. Michael Torres",
                InstructorBio = "Dr. Torres researches algorithm optimization and competitive programming strategies.",
                IsFeatured = false
            },
            new()
            {
                Id = "cs301", Code = "CS 301", Title = "Database Systems",
                Description = "Relational database design, SQL, transaction processing, and introduction to NoSQL databases.",
                DepartmentId = "cs", DepartmentName = "Computer Science", Credits = 3,
                Schedule = "Mon/Wed 2:00–3:15 PM", InstructorName = "Dr. Lisa Park",
                InstructorBio = "Dr. Park has industry experience at major tech companies and focuses on scalable data systems.",
                IsFeatured = true
            },
            new()
            {
                Id = "math101", Code = "MATH 101", Title = "Calculus I",
                Description = "Limits, derivatives, and integrals of single-variable functions with applications.",
                DepartmentId = "math", DepartmentName = "Mathematics", Credits = 4,
                Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. James Wright",
                InstructorBio = "Dr. Wright is an award-winning educator known for making calculus accessible to all students.",
                IsFeatured = true
            },
            new()
            {
                Id = "math201", Code = "MATH 201", Title = "Linear Algebra",
                Description = "Vector spaces, matrices, linear transformations, eigenvalues, and applications.",
                DepartmentId = "math", DepartmentName = "Mathematics", Credits = 3,
                Schedule = "Tue/Thu 1:00–2:15 PM", InstructorName = "Dr. Anna Petrov",
                InstructorBio = "Dr. Petrov researches applied linear algebra in machine learning contexts.",
                IsFeatured = false
            },
            new()
            {
                Id = "eng101", Code = "ENG 101", Title = "Composition & Rhetoric",
                Description = "Development of academic writing skills including argumentation, research methods, and critical analysis.",
                DepartmentId = "eng", DepartmentName = "English", Credits = 3,
                Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Prof. David Kim",
                InstructorBio = "Prof. Kim publishes on rhetoric in digital media and coaches the university debate team.",
                IsFeatured = false
            },
            new()
            {
                Id = "eng202", Code = "ENG 202", Title = "American Literature",
                Description = "Survey of American literary works from the colonial period to the present day.",
                DepartmentId = "eng", DepartmentName = "English", Credits = 3,
                Schedule = "Tue/Thu 9:00–10:15 AM", InstructorName = "Dr. Rachel Okafor",
                InstructorBio = "Dr. Okafor specializes in 20th-century American fiction and narrative theory.",
                IsFeatured = true
            },
            new()
            {
                Id = "phys101", Code = "PHYS 101", Title = "General Physics I",
                Description = "Mechanics, thermodynamics, and waves. Includes weekly laboratory sessions.",
                DepartmentId = "phys", DepartmentName = "Physics", Credits = 4,
                Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Thu Lab 2:00–4:00 PM", InstructorName = "Dr. Robert Singh",
                InstructorBio = "Dr. Singh's research focuses on experimental condensed matter physics.",
                IsFeatured = false
            },
            new()
            {
                Id = "hist101", Code = "HIST 101", Title = "World Civilizations",
                Description = "Survey of major world civilizations from ancient times through the early modern period.",
                DepartmentId = "hist", DepartmentName = "History", Credits = 3,
                Schedule = "Tue/Thu 11:00 AM–12:15 PM", InstructorName = "Dr. Maria Gonzalez",
                InstructorBio = "Dr. Gonzalez is a specialist in comparative world history and cross-cultural exchange.",
                IsFeatured = false
            },
            new()
            {
                Id = "hist250", Code = "HIST 250", Title = "Modern European History",
                Description = "Europe from the Enlightenment to the present: revolutions, wars, and social transformations.",
                DepartmentId = "hist", DepartmentName = "History", Credits = 3,
                Schedule = "Mon/Wed 3:30–4:45 PM", InstructorName = "Dr. Thomas Burke",
                InstructorBio = "Dr. Burke has published extensively on 19th-century European political movements.",
                IsFeatured = false
            },
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(string id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? departmentId = null, string? search = null)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(departmentId))
        {
            query = query.Where(c => c.DepartmentId == departmentId);
        }

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(string id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();
}

