@page "/"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>University Course Catalog</PageTitle>

<div class="container">
    <div class="text-center my-4">
        <h1>University Course Catalog</h1>
        <p class="lead">Browse courses, explore departments, and enroll for the upcoming semester.</p>
    </div>

    <section class="mb-5">
        <h2>Featured Courses</h2>
        <div class="row">
            @foreach (var course in _featuredCourses)
            {
                <div class="col-md-6 col-lg-4 mb-3">
                    <div class="card h-100">
                        <div class="card-body">
                            <h5 class="card-title">@course.Code — @course.Title</h5>
                            <p class="card-text text-muted">@course.DepartmentName · @course.Credits credits</p>
                            <p class="card-text">@course.Description[..Math.Min(course.Description.Length, 100)]…</p>
                        </div>
                        <div class="card-footer">
                            <a href="/courses/@course.Id" class="btn btn-primary btn-sm">View Details</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    </section>

    <section class="mb-5">
        <h2>Departments</h2>
        <div class="list-group">
            @foreach (var dept in _departments)
            {
                <a href="/courses?department=@dept.Id" class="list-group-item list-group-item-action d-flex justify-content-between align-items-center">
                    <div>
                        <strong>@dept.Name</strong>
                        <br /><small class="text-muted">@dept.Description</small>
                    </div>
                    <span class="badge bg-secondary rounded-pill">@Catalog.GetCourses(dept.Id).Count courses</span>
                </a>
            }
        </div>
    </section>

    <div class="text-center">
        <a href="/courses" class="btn btn-outline-primary me-2">Browse All Courses</a>
        <a href="/enroll" class="btn btn-success">Enroll Now</a>
    </div>
</div>

@code {
    private List<Course> _featuredCourses = new();
    private List<Department> _departments = new();

    protected override void OnInitialized()
    {
        _featuredCourses = Catalog.GetFeaturedCourses();
        _departments = Catalog.GetDepartments();
    }
}

@page "/courses"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>Courses — University Course Catalog</PageTitle>

<div class="container">
    <h1 class="my-4">Course Catalog</h1>

    <form method="get" class="row g-3 mb-4">
        <div class="col-md-6">
            <input type="text" name="search" value="@Search" class="form-control" placeholder="Search courses by title, code, or instructor..." />
        </div>
        <div class="col-md-4">
            <select name="department" class="form-select">
                <option value="">All Departments</option>
                @foreach (var dept in _departments)
                {
                    <option value="@dept.Id" selected="@(Department == dept.Id)">@dept.Name</option>
                }
            </select>
        </div>
        <div class="col-md-2">
            <button type="submit" class="btn btn-primary w-100">Filter</button>
        </div>
    </form>

    @if (_courses.Count == 0)
    {
        <div class="alert alert-info">No courses found matching your criteria.</div>
    }
    else
    {
        <p class="text-muted">Showing @_courses.Count course(s)</p>
        <div class="table-responsive">
            <table class="table table-striped table-hover">
                <thead>
                    <tr>
                        <th>Code</th>
                        <th>Title</th>
                        <th>Department</th>
                        <th>Credits</th>
                        <th>Instructor</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var course in _courses)
                    {
                        <tr>
                            <td>@course.Code</td>
                            <td>@course.Title</td>
                            <td>@course.DepartmentName</td>
                            <td>@course.Credits</td>
                            <td>@course.InstructorName</td>
                            <td><a href="/courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
    }
</div>

@code {
    [SupplyParameterFromQuery] public string? Search { get; set; }
    [SupplyParameterFromQuery] public string? Department { get; set; }

    private List<Department> _departments = new();
    private List<Course> _courses = new();

    protected override void OnInitialized()
    {
        _departments = Catalog.GetDepartments();
        _courses = Catalog.GetCourses(Department, Search);
    }
}

@page "/courses/{CourseId}"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>@(_course?.Title ?? "Course Not Found") — University Course Catalog</PageTitle>

<div class="container">
    @if (_course is null)
    {
        <div class="alert alert-warning my-4">Course not found.</div>
        <a href="/courses" class="btn btn-secondary">Back to Catalog</a>
    }
    else
    {
        <nav class="my-3">
            <a href="/courses">← Back to Catalog</a>
        </nav>

