@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>Enrollment Request — University Course Catalog</PageTitle>

<div class="container">
    <h1 class="my-4">Enrollment Request</h1>

    @if (_submitted)
    {
        <div class="alert alert-success">
            <h4>Request Submitted!</h4>
            <p>Thank you, <strong>@_model.StudentName</strong>. Your enrollment request for <strong>@_selectedCourseTitle</strong> has been received. You will be notified once it is processed.</p>
        </div>
        <a href="/courses" class="btn btn-primary">Browse More Courses</a>
    }
    else
    {
        <p class="text-muted mb-4">Fill out the form below to request enrollment in a course. All fields are required.</p>

        <EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="EnrollmentForm" method="post">
            <AntiforgeryToken />
            <DataAnnotationsValidator />
            <ValidationSummary class="text-danger mb-3" />

            <div class="mb-3">
                <label for="studentName" class="form-label">Full Name</label>
                <InputText id="studentName" @bind-Value="_model.StudentName" class="form-control" />
                <ValidationMessage For="() => _model.StudentName" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="studentId" class="form-label">Student ID</label>
                <InputText id="studentId" @bind-Value="_model.StudentId" class="form-control" placeholder="e.g., STU-12345" />
                <ValidationMessage For="() => _model.StudentId" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="courseId" class="form-label">Course</label>
                <InputSelect id="courseId" @bind-Value="_model.CourseId" class="form-select">
                    <option value="">— Select a course —</option>
                    @foreach (var course in _courses)
                    {
                        <option value="@course.Id">@course.Code — @course.Title (@course.Credits cr)</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => _model.CourseId" class="text-danger" />
            </div>

            <button type="submit" class="btn btn-success">Submit Enrollment Request</button>
            <a href="/courses" class="btn btn-outline-secondary ms-2">Cancel</a>
        </EditForm>
    }
</div>

@code {
    [SupplyParameterFromForm] private EnrollmentRequest _model { get; set; } = new();
    [SupplyParameterFromQuery] public string? CourseId { get; set; }

    private List<Course> _courses = new();
    private bool _submitted;
    private string _selectedCourseTitle = string.Empty;

    protected override void OnInitialized()
    {
        _courses = Catalog.GetCourses();

        if (!string.IsNullOrEmpty(CourseId) && string.IsNullOrEmpty(_model.CourseId))
        {
            _model.CourseId = CourseId;
        }
    }

    private void HandleSubmit()
    {
        var course = Catalog.GetCourse(_model.CourseId);
        _selectedCourseTitle = course is not null ? $"{course.Code} — {course.Title}" : _model.CourseId;
        _submitted = true;
    }
}
